91	// DeleteDraft 删除一条尚未生效的草稿及其记录。草稿从未生效，
92	// 因此删除不影响任何生效内容，也不产生审计事件。
93	func (s *Store) DeleteDraft(actor Actor, recordID ID) error {
94		if !actor.valid() || !actor.IsInternal() {
