		return nil, err
	}

	s := &Store{dir: dir, clock: time.Now, lock: lockFile}
	for _, opt := range opts {
		opt(s)
	}
	if s.clock == nil {
		s.clock = time.Now
	}

	if err := s.loadLocked(); err != nil {
		unlockFile(lockFile)
		lockFile.Close()
		return nil, err
	}
