683	// snapshotExpectedAudits 复制期望审计序列，避免 append 复用底层数组改动原切片。
684	func snapshotExpectedAudits(in []expectedAudit) []expectedAudit {
685		out := make([]expectedAudit, len(in))
686		copy(out, in)
687		return out
688	}
689	
690	// idList 列出就诊标识，用于失败信息。
691	func idList(es []Encounter) []ID {
692		ids := make([]ID, len(es))
693		for i, e := range es {
694			ids[i] = e.ID
695		}
696		return ids
697	}
698	
699	// ---- 关闭后从同一目录重开：跨患者归属、排序与审计次序在 JSON 恢复后不变 ----
700	
701	func TestChartPatientScopingSurvivesReopen(t *testing.T) {
702		dir := t.TempDir()
703		clk := &fakeClock{t: time.Date(2026, 5, 1, 8, 0, 0, 0, time.UTC)}
704		open := func() *Store {
705			s, err := Open(dir, WithClock(func() time.Time { return clk.t }))
706			if err != nil {
707				t.Fatalf("open: %v", err)
708			}
709			return s
710		}
711	
712		s := open()
713		pa, err := s.RegisterPatient(doc, "重开患者甲")
714		if err != nil {
715			t.Fatal(err)
716		}
717		pb, err := s.RegisterPatient(doc2, "重开患者乙")
718		if err != nil {
719			t.Fatal(err)
720		}
721		at := clk.t
722		// 两名患者各有两次同刻就诊。
723		a1, err := s.AddEncounter(doc, pa.ID, at)
724		if err != nil {
725			t.Fatal(err)
726		}
727		b1, err := s.AddEncounter(doc2, pb.ID, at)
728		if err != nil {
729			t.Fatal(err)
730		}
731		a2, err := s.AddEncounter(doc, pa.ID, at)
732		if err != nil {
733			t.Fatal(err)
734		}
735		b2, err := s.AddEncounter(doc2, pb.ID, at)
736		if err != nil {
737			t.Fatal(err)
738		}
739	
740		const shared = "重开后仍须归属正确的相同文字"
741		aDraft, err := s.CreateDraft(doc, pa.ID, a1.ID, Diagnosis, shared)
742		if err != nil {
743			t.Fatal(err)
744		}
745		bDraft, err := s.CreateDraft(doc2, pb.ID, b1.ID, Diagnosis, shared)
746		if err != nil {
747			t.Fatal(err)
748		}
749		aRec, err := s.CreateDraft(doc, pa.ID, a2.ID, Order, shared)
750		if err != nil {
751			t.Fatal(err)
752		}
753		bRec, err := s.CreateDraft(doc2, pb.ID, b2.ID, Order, shared)
754		if err != nil {
755			t.Fatal(err)
756		}
757	
758		clk.t = at.Add(time.Hour)
759		ts := clk.t
760		// 同刻交错：甲生效、乙生效、甲更正、乙更正，验证同刻追加次序在重开后仍保留。
761		aV1 := activateAs(t, s, doc, aRec.ID)
762		bV1 := activateAs(t, s, doc2, bRec.ID)
763		clk.t = ts.Add(time.Hour)
764		tc := clk.t
765		aV2 := correctAs(t, s, doc2, aRec.ID, 1, shared+"（甲更正）", "甲的更正原因")
766		bV2 := correctAs(t, s, doc, bRec.ID, 1, shared+"（乙更正）", "乙的更正原因")
767	
768		beforeA, err := s.Chart(doc2, pa.ID)
769		if err != nil {
770			t.Fatal(err)
771		}
772		beforeB, err := s.Chart(doc, pb.ID)
773		if err != nil {
774			t.Fatal(err)
775		}
776	
777		if err := s.Close(); err != nil {
778			t.Fatal(err)
779		}
780		s2 := open()
781		t.Cleanup(func() { _ = s2.Close() })
782	
783		afterA, err := s2.Chart(doc2, pa.ID)
784		if err != nil {
785			t.Fatalf("chart A after reopen: %v", err)
786		}
787		afterB, err := s2.Chart(doc, pb.ID)
788		if err != nil {
789			t.Fatalf("chart B after reopen: %v", err)
790		}
791		if !reflect.DeepEqual(afterA, beforeA) {
792			t.Fatalf("chart A changed across reopen:\n before=%+v\n after =%+v", beforeA, afterA)
793		}
794		if !reflect.DeepEqual(afterB, beforeB) {
795			t.Fatalf("chart B changed across reopen:\n before=%+v\n after =%+v", beforeB, afterB)
796		}
797	
798		// 归属在恢复后仍严格成立。
799		wantAEnc := []ID{a1.ID, a2.ID}
800		wantBEnc := []ID{b1.ID, b2.ID}
801		sort.Strings(wantAEnc)
802		sort.Strings(wantBEnc)
803		if got := idList(afterA.Encounters); !reflect.DeepEqual(got, wantAEnc) {
804			t.Fatalf("after reopen chart A encounters = %v, want %v", got, wantAEnc)
805		}
806		if got := idList(afterB.Encounters); !reflect.DeepEqual(got, wantBEnc) {
807			t.Fatalf("after reopen chart B encounters = %v, want %v", got, wantBEnc)
808		}
809		assertEncounterOrder(t, afterA.Encounters, "reopened chart A encounters")
810		assertEncounterOrder(t, afterB.Encounters, "reopened chart B encounters")
811	
812		aMap := historiesByID(afterA.Records)
813		bMap := historiesByID(afterB.Records)
814		if _, ok := aMap[aDraft.ID]; !ok {
815			t.Fatal("after reopen chart A lost its draft")
816		}
817		if _, ok := bMap[bDraft.ID]; !ok {
818			t.Fatal("after reopen chart B lost its draft")
819		}
820		if _, ok := aMap[bRec.ID]; ok {
821			t.Fatal("after reopen patient B record leaked into chart A")
822		}
823		if _, ok := bMap[aRec.ID]; ok {
824			t.Fatal("after reopen patient A record leaked into chart B")
825		}
826		if h := aMap[aRec.ID]; len(h.Versions) != 2 || h.CurrentVersion.ID != aV2.ID ||
827			h.Versions[1].PrevID != aV1.ID || h.Versions[1].Reason != "甲的更正原因" {
828			t.Fatalf("after reopen chart A history broken: %+v", h.Versions)
829		}
830		if h := bMap[bRec.ID]; len(h.Versions) != 2 || h.CurrentVersion.ID != bV2.ID ||
831			h.Versions[1].PrevID != bV1.ID || h.Versions[1].Reason != "乙的更正原因" {
832			t.Fatalf("after reopen chart B history broken: %+v", h.Versions)
833		}
834	
835		// 同刻交错的审计在重开后仍按真实追加次序、真实操作人归属各患者。
836		assertAuditSequence(t, afterA.AuditEvents, pa.ID, []expectedAudit{
837			{ActionActivated, "record", aRec.ID, doc.ID, ts},
838			{ActionCorrected, "record", aRec.ID, doc2.ID, tc},
839		}, "reopened chart A audits")
840		assertAuditSequence(t, afterB.AuditEvents, pb.ID, []expectedAudit{
841			{ActionActivated, "record", bRec.ID, doc2.ID, ts},
842			{ActionCorrected, "record", bRec.ID, doc.ID, tc},
843		}, "reopened chart B audits")
844	
845		// 接收方重开后依然不能通过 Chart 取档案。
846		if _, err := s2.Chart(rcv, pa.ID); !errors.Is(err, ErrAccessDenied) {
847			t.Fatalf("receiver chart after reopen err = %v, want ErrAccessDenied", err)
848		}
849	}
